<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/lacms_security.php';requireLacmsPermission('lacms.users.manage');$q=db()->prepare('SELECT u.full_name,u.email,r.name role_name,u.status,usa.access_level,usa.status access_status,u.last_login_at FROM users u LEFT JOIN roles r ON r.id=u.role_id LEFT JOIN user_system_access usa ON usa.user_id=u.id AND usa.system_id=:system WHERE u.deleted_at IS NULL ORDER BY u.full_name');$q->execute([':system'=>lacmsSystemId()]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>LACMS Users</title><style>body{font:11px Arial;margin:20px}.head{text-align:center;border-bottom:3px solid #0f2137}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{border:1px solid #bbb;padding:5px}th{background:#eee}</style></head><body onload="window.print()"><div class="head"><h2>LACMS Shared User Access Registry</h2><p>Generated <?= date('F j, Y g:i A') ?></p></div><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Account</th><th>LACMS Access</th><th>Level</th><th>Last Login</th></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><?= e($u['full_name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['role_name']?:'—') ?></td><td><?= e($u['status']) ?></td><td><?= e($u['access_status']?:'Inactive') ?></td><td><?= e($u['access_level']?:'Standard') ?></td><td><?= e($u['last_login_at']?:'Never') ?></td></tr><?php endforeach; ?></tbody></table></body></html>
